package com.bank.fee;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.ArrayDeque;
import java.util.Deque;

// Evaluates a postfix (Reverse Polish) arithmetic expression.
public class PostfixEvaluator {

    // Tokens are separated by spaces, e.g. "100000 0.02 * 500 +".
    public BigDecimal evaluate(String expression) {
        Deque<BigDecimal> stack = new ArrayDeque<>();
        for (String token : expression.trim().split("\\s+")) {
            if (isOperator(token)) {
                if (stack.size() < 2) {
                    throw new IllegalArgumentException("Malformed expression: not enough operands");
                }
                BigDecimal right = stack.pop();  // most recent = right operand
                BigDecimal left = stack.pop();   // earlier     = left operand
                stack.push(apply(left, right, token));
            } else {
                stack.push(new BigDecimal(token));
            }
        }
        if (stack.size() != 1) {
            throw new IllegalArgumentException("Malformed expression: leftover operands");
        }
        return stack.pop();
    }

    private boolean isOperator(String token) {
        return token.equals("+") || token.equals("-")
                || token.equals("*") || token.equals("/");
    }

    private BigDecimal apply(BigDecimal a, BigDecimal b, String op) {
        return switch (op) {
            case "+" -> a.add(b);
            case "-" -> a.subtract(b);
            case "*" -> a.multiply(b);
            case "/" -> a.divide(b, 2, RoundingMode.HALF_UP); // money: 2 dp
            default -> throw new IllegalArgumentException("Unknown operator: " + op);
        };
    }
}
