package com.bank.fee;

import java.math.BigDecimal;
import java.util.logging.Logger;

// Evaluates stored fee formulas written in postfix notation.
public class FeeCalculationService {

    private static final Logger log = Logger.getLogger(FeeCalculationService.class.getName());
    private final PostfixEvaluator evaluator;

    public FeeCalculationService(PostfixEvaluator evaluator) {
        this.evaluator = evaluator;
    }

    public BigDecimal computeFee(String formula) {
        try {
            BigDecimal fee = evaluator.evaluate(formula);
            log.info(() -> "Formula [" + formula + "] evaluated to fee = " + fee);
            return fee;
        } catch (IllegalArgumentException e) {
            log.severe(() -> "Rejected formula [" + formula + "]: " + e.getMessage());
            throw e;
        }
    }
}
