package com.bank.fee;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class PostfixEvaluatorDemo {

    private static final Logger log = Logger.getLogger(PostfixEvaluatorDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Fee Formula Engine (postfix)");
        FeeCalculationService service = new FeeCalculationService(new PostfixEvaluator());

        // 2% of 100000, plus flat 500 = 2000 + 500 = 2500
        service.computeFee("100000 0.02 * 500 +");
        // 50000 divided across 4 instalments = 12500.00
        service.computeFee("50000 4 /");
        // 10000 minus 250 discount = 9750
        service.computeFee("10000 250 -");
    }
}
